@namespace sv_64067063d5884d63897e3f2212c70a3b.Components.Pages.Apply

@using sv_64067063d5884d63897e3f2212c70a3b.Models

<fieldset class="work-entry-form">
    <legend>Position @(Index + 1)</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn btn-outline-danger btn-sm float-end" @onclick="OnRemove">Remove</button>
    }

    <div class="row g-3 mb-3">
        <div class="col-md-6">
            <label class="form-label">Company Name</label>
            <input class="form-control" @bind="Entry.Company" @bind:event="oninput" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Job Title</label>
            <input class="form-control" @bind="Entry.Title" @bind:event="oninput" />
        </div>
    </div>

    <div class="row g-3 mb-3">
        <div class="col-md-4">
            <label class="form-label">Start Date</label>
            <input type="date" class="form-control" @bind="Entry.StartDate" />
        </div>
        <div class="col-md-4">
            <label class="form-label">End Date</label>
            <input type="date" class="form-control" @bind="Entry.EndDate" disabled="@Entry.IsCurrent" />
        </div>
        <div class="col-md-4 d-flex align-items-end">
            <div class="form-check">
                <input type="checkbox" class="form-check-input" id="current-@Index" @bind="Entry.IsCurrent"
                    @onclick="HandleCurrentToggle" />
                <label class="form-check-label" for="current-@Index">Currently working here</label>
            </div>
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label">Description</label>
        <textarea class="form-control" rows="3" @bind="Entry.Description" @bind:event="oninput"></textarea>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void HandleCurrentToggle()
    {
        if (!Entry.IsCurrent)
        {
            Entry.EndDate = null;
        }
    }
}

