@page "/apply"
@rendermode InteractiveServer

@using sv_64067063d5884d63897e3f2212c70a3b.Components.Pages.Apply
@using sv_64067063d5884d63897e3f2212c70a3b.Models
@using sv_64067063d5884d63897e3f2212c70a3b.Services

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Job Application</h1>

    <StepIndicator CurrentStep="currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="personalInfo"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="workEntries"
                OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="references"
                OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep @bind-CoverLetterText="coverLetter"
                OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Personal="personalInfo"
                WorkEntries="workEntries"
                References="references"
                CoverLetter="coverLetter"
                OnBack="PreviousStep"
                OnEditSection="GoToStep"
                SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private int currentStep;
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private void NextStep() => currentStep++;
    private void PreviousStep() => currentStep--;
    private void GoToStep(int step) => currentStep = step;

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
            new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate!.Value, e.IsCurrent ? null : e.EndDate, e.Description)
            ).ToList()),
            references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)
            ).ToList(),
            coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

nav.step-indicator ol {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    counter-reset: step;
}

.step-item {
    flex: 1;
    text-align: center;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-item + .step-item::before {
    content: "";
    position: absolute;
    top: 18px;
    left: -50%;
    width: 100%;
    height: 2px;
    background: #dee2e6;
    z-index: 0;
}

.step-item.completed + .step-item::before,
.step-item.active + .step-item::before {
    background: #0d6efd;
}

/* Also color the line before completed items */
.step-item.completed + .step-item.completed::before {
    background: #0d6efd;
}

.step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: #dee2e6;
    color: #6c757d;
    font-weight: 600;
    position: relative;
    z-index: 1;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    background: #0d6efd;
    color: #fff;
}

.step-item.completed .step-circle {
    background: #198754;
    color: #fff;
}

.step-item.future .step-circle {
    background: #dee2e6;
    color: #adb5bd;
}

.step-label {
    display: block;
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: #6c757d;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-check {
    font-size: 1rem;
}

.step-content {
    max-width: 720px;
    margin: 0 auto;
}

fieldset.work-entry-form,
fieldset.reference-form {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1rem 1.25rem;
    margin-bottom: 1rem;
}

fieldset legend {
    font-size: 1rem;
    font-weight: 600;
    width: auto;
    padding: 0 0.5rem;
    float: none;
}

